<div class="accessibility-widget"><button class="floating-button" data-bs-toggle="offcanvas" data-bs-target="#accessibilityPanel" aria-label="Accessibility"><i class="fas fa-universal-access"></i></button></div><div class="offcanvas offcanvas-end" id="accessibilityPanel"><div class="offcanvas-header"><h5>Accessibility</h5><button class="btn-close" data-bs-dismiss="offcanvas"></button></div><div class="offcanvas-body d-grid gap-2"><button class="btn btn-outline-secondary" onclick="Accessibility.font(1)">Increase text</button><button class="btn btn-outline-secondary" onclick="Accessibility.font(-1)">Decrease text</button><button class="btn btn-outline-secondary" onclick="Accessibility.toggle('high-contrast')">High contrast</button><button class="btn btn-outline-secondary" onclick="Accessibility.toggle('grayscale')">Grayscale</button><button class="btn btn-outline-secondary" onclick="Accessibility.toggle('reduce-motion')">Reduce motion</button><button class="btn btn-outline-danger" onclick="Accessibility.reset()">Reset</button></div></div>
